 rec=dict(status='query_only_conservative_semantic_sensitivity_complete_not_gold',datasets=out,root_review=check,source_classification_sha256=hashlib.sha256((D/'text_classification_v4.json').read_bytes()).hexdigest(),POS_annotation_sha256=hashlib.sha256((D/'semantic_annotation_v1.json').read_bytes()).hexdigest(),elapsed_wall_seconds=time.perf_counter()-start,no_GT_or_metrics_read=True,new_Source=0,new_expert=0,new_NLP_model=0)
 p=D/'conservative_text_sensitivity_v1.json';p.write_text(json.dumps(rec,ensure_ascii=False,indent=2)+'\n');public=dict(status=rec['status'],counts={ds:v['counts']for ds,v in out.items()},review_total=len(check),review_retained=sum(x['retained']for x in check),review_retained_agreements=sum(x['retained']and x['agrees']for x in check),review_retained_disagreements=sum(x['retained']and not x['agrees']for x in check),root_single_AI_review_not_independent_human_gold=True,scope='Strict subset only; unknown vocabulary abstains. Static visual/layout proxy is not pure appearance-only. Original full operational groups and failed POS cases retained, no outcome-based selection.',annotation_sha256=hashlib.sha256(p.read_bytes()).hexdigest());q=R/'results/temporal_feedback_risk_v1/conservative_semantic_validation_v1.json';q.write_text(json.dumps(public,indent=2)+'\n');print(json.dumps(public))
